(6372842, 944594, 10785, '<td valign="top">Great composition! I think the blacks could have been a hair darker. The border doesn''t bother me either way. There is some extreme digital artifacts going on at the black keys. It''s more than just digital noise... especially on the lower black key.</td>', 'Great composition! I think the blacks could have been a hair darker. The border doesn''t bother me either way. There is some extreme digital artifacts going on at the black keys. It''s more than just digital noise... especially on the lower black key.', '2011-04-04 14:19:25.000000', NULL, 1),
(6372855, 944301, 98022, '<td valign="top">Nice shot, lots of good detail in the feathers and nice range of tones. But the sharpening halos around the goose on the right are pretty bad. Since this was an advanced editing challenge, you could have removed those. There is a very good tutorial on the site on how to easily do this. :)</td>', 'Nice shot, lots of good detail in the feathers and nice range of tones. But the sharpening halos around the goose on the right are pretty bad. Since this was an advanced editing challenge, you could have removed those. There is a very good tutorial on the site on how to easily do this. :)', '2011-04-04 14:31:37.000000', NULL, 1),
(6372860, 943676, 30669, '<td valign="top">Beautiful Shot - 10</td>', 'Beautiful Shot - 10', '2011-04-04 14:37:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6372901, 943999, 117474, '<td valign="top">Lovely. I don''t mind the lens flare here, or the grittiness. I think they add to it. <br/>I wonder if you would have been permitted to straighten the horizon for this. A flat line might have more impact. Just what I might have done--not saying it would have made it better or anything :-) 7</td>', 'Lovely. I don''t mind the lens flare here, or the grittiness. I think they add to it. I wonder if you would have been permitted to straighten the horizon for this. A flat line might have more impact. Just what I might have done--not saying it would have made it better or anything :-) 7', '2011-04-04 15:32:21.000000', NULL, 1),
