(6372923, 944396, 99780, '<td valign="top">I really like her expression and the kind of ethereal quality to the whole image but i''m not crazy about the angled view.  nice work.</td>', 'I really like her expression and the kind of ethereal quality to the whole image but i''m not crazy about the angled view.  nice work.', '2011-04-04 15:55:47.000000', NULL, 1),
(6372937, 944499, 106484, '<td valign="top">I like the shot, but i''m not too keen on the strong post-processing. It has left a white halo around the boots.</td>', 'I like the shot, but i''m not too keen on the strong post-processing. It has left a white halo around the boots.', '2011-04-04 16:15:00.000000', NULL, 1),
(6372941, 943999, 54844, '<td valign="top">I like this, however, I think (In my opinion) it would have been a stellar shot if the sun had set (Or rose), and there was no lens flare.</td>', 'I like this, however, I think (In my opinion) it would have been a stellar shot if the sun had set (Or rose), and there was no lens flare.', '2011-04-04 16:18:48.000000', NULL, 1),
