(6373276, 944324, 100393, '<td valign="top">Great idea but if I''m honest this doesn''t look as polished as your stuff. Having said that, this still goes above and beyond in terms of dedication.</td>', 'Great idea but if I''m honest this doesn''t look as polished as your stuff. Having said that, this still goes above and beyond in terms of dedication.', '2011-04-04 19:57:05.000000', NULL, 1),
(6373283, 944382, 100393, '<td valign="top">Brilliant and bold - that low contrast on the left should be ugly but is utterly masterful.</td>', 'Brilliant and bold - that low contrast on the left should be ugly but is utterly masterful.', '2011-04-04 20:00:25.000000', NULL, 1),
(6373284, 944418, 66641, '<td valign="top">I would like to see a different crop on this, but not sure what.  Maybe less of the bottom?  Still a nice shot.</td>', 'I would like to see a different crop on this, but not sure what.  Maybe less of the bottom?  Still a nice shot.', '2011-04-04 20:00:27.000000', NULL, 1),
