(6375064, 944090, 116631, '<td valign="top">took me a minute to realize that it was a waterfall and not a rotated picture!  nice effect!</td>', 'took me a minute to realize that it was a waterfall and not a rotated picture!  nice effect!', '2011-04-05 14:41:38.000000', NULL, 1),
(6375066, 944373, 116631, '<td valign="top">all greys..would be better if you adjusted your levels</td>', 'all greys..would be better if you adjusted your levels', '2011-04-05 14:42:39.000000', NULL, 1),
(6375077, 944510, 116631, '<td valign="top">LOL!</td>', 'LOL!', '2011-04-05 14:52:34.000000', NULL, 1),
(6375083, 944246, 116631, '<td valign="top">this would be great it it were all in focus!</td>', 'this would be great it it were all in focus!', '2011-04-05 14:55:31.000000', NULL, 1),
(6375182, 943888, 117534, '<td valign="top">Stunning, Beautiful, WOW... Your processing is weird and strange and I love it! Very Unique Photo! Ummm after reading the B/W thread I think I should elaborate on the weird/strange comment.. To me your subjects head and espically the eyes are out of proportion to the rest of her body, The eyes drew me into the photo, then my eyes were drawn around the face and finally off to the hands shoulders and background. I found that a very enjoyable journey around a photo! ( I am also very curious as to how you did this) I hope you are scoreing well with this, Personaly I am all about the eyes in a photo, to me they set the whole mood.</td>', 'Stunning, Beautiful, WOW... Your processing is weird and strange and I love it! Very Unique Photo! Ummm after reading the B/W thread I think I should elaborate on the weird/strange comment.. To me your subjects head and espically the eyes are out of proportion to the rest of her body, The eyes drew me into the photo, then my eyes were drawn around the face and finally off to the hands shoulders and background. I found that a very enjoyable journey around a photo! ( I am also very curious as to how you did this) I hope you are scoreing well with this, Personaly I am all about the eyes in a photo, to me they set the whole mood.', '2011-04-05 16:13:31.000000', NULL, 1),
(6375195, 944396, 117534, '<td valign="top">Sharp Crisp beautiful eyes, and face. The thumbnail dosen''t do this justice, it looked blown out, and I just opened it full and it''s not in any way. I''m just a novice trying to improve my "eye" so don''t yell at me... the only thing I see I would improve on is the headband across her forehead maybe you could have burned in a tiny bit more detail, On my computor screen it almost blends in with the hair right there.. That being said, I still think it''s a way above average photo.. 7</td>', 'Sharp Crisp beautiful eyes, and face. The thumbnail dosen''t do this justice, it looked blown out, and I just opened it full and it''s not in any way. I''m just a novice trying to improve my "eye" so don''t yell at me... the only thing I see I would improve on is the headband across her forehead maybe you could have burned in a tiny bit more detail, On my computor screen it almost blends in with the hair right there.. That being said, I still think it''s a way above average photo.. 7', '2011-04-05 16:26:01.000000', NULL, 1),
(6375277, 944364, 16148, '<td valign="top">NIcely done.</td>', 'NIcely done.', '2011-04-05 18:07:20.000000', NULL, 1),
(6375290, 944463, 16106, '<td valign="top">I am puzzled by the title. this is a lovely image with a good focal point and some nice tones and textures, but the title makes us think of something that isn''t in the image. Im also not too keen on the stair edge that is just barely in the frame, it draws they eye and has nothing to say. the stairs, the drips and the bird are all very solid.</td>', 'I am puzzled by the title. this is a lovely image with a good focal point and some nice tones and textures, but the title makes us think of something that isn''t in the image. Im also not too keen on the stair edge that is just barely in the frame, it draws they eye and has nothing to say. the stairs, the drips and the bird are all very solid.', '2011-04-05 18:19:22.000000', NULL, 1),
(6375292, 944115, 16106, '<td valign="top">Beautifully lit, processed and presented. Oh and it helps that she is pretty and you got a nice transitional expression. Is this Gary?</td>', 'Beautifully lit, processed and presented. Oh and it helps that she is pretty and you got a nice transitional expression. Is this Gary?', '2011-04-05 18:21:39.000000', NULL, 1),
(6375293, 944487, 16106, '<td valign="top">I do love the weird narrative here. A small slice of normal life presented as if it is special, almost mythic. Very nice processing.</td>', 'I do love the weird narrative here. A small slice of normal life presented as if it is special, almost mythic. Very nice processing.', '2011-04-05 18:23:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6375312, 944246, 16106, '<td valign="top">I like the framing, the massing and the tones. I miss the detail the the limited focal plane leaves out. If all the details had been there this would have been top five.</td>', 'I like the framing, the massing and the tones. I miss the detail the the limited focal plane leaves out. If all the details had been there this would have been top five.', '2011-04-05 18:51:48.000000', NULL, 1),
(6375371, 944596, 39057, '<td valign="top">Almost missed the pigeon. Glad I saw him. 4 without the bird.....7 with.</td>', 'Almost missed the pigeon. Glad I saw him. 4 without the bird.....7 with.', '2011-04-05 20:31:27.000000', NULL, 1),
(6375374, 944578, 16148, '<td valign="top">This image pulls you in.  Everything is converging towards the center.</td>', 'This image pulls you in.  Everything is converging towards the center.', '2011-04-05 20:32:38.000000', NULL, 1),
(6375384, 944588, 109227, '<td valign="top">Absolutely gorgeous.  My favorite of the challenge.</td>', 'Absolutely gorgeous.  My favorite of the challenge.', '2011-04-05 20:48:09.000000', NULL, 1),
(6375385, 943419, 109227, '<td valign="top">I really love the feel of this image.  Nicely done.  Top 10, imo.</td>', 'I really love the feel of this image.  Nicely done.  Top 10, imo.', '2011-04-05 20:48:35.000000', NULL, 1),
(6375389, 944114, 2553, '<td valign="top">Nicely composed and b&amp;w treatment is well-done, with great contrasts that really work well.</td>', 'Nicely composed and b&w treatment is well-done, with great contrasts that really work well.', '2011-04-05 20:50:08.000000', NULL, 1),
(6375390, 944591, 109227, '<td valign="top">Great clarity and I like the processing.</td>', 'Great clarity and I like the processing.', '2011-04-05 20:50:42.000000', NULL, 1),
(6375392, 944371, 2553, '<td valign="top">Love this.  Wonderful to look at, the great lines draw you right in.</td>', 'Love this.  Wonderful to look at, the great lines draw you right in.', '2011-04-05 20:51:15.000000', NULL, 1),
(6375394, 944115, 2553, '<td valign="top">Beautiful in every way.</td>', 'Beautiful in every way.', '2011-04-05 20:52:02.000000', NULL, 1),
(6375396, 944193, 2553, '<td valign="top">Nicely done b&amp;w, love the toning.</td>', 'Nicely done b&w, love the toning.', '2011-04-05 20:53:01.000000', NULL, 1),
(6375397, 943947, 2553, '<td valign="top">Love the curvy lines, especially in contrast to the sharp edged buildings.</td>', 'Love the curvy lines, especially in contrast to the sharp edged buildings.', '2011-04-05 20:53:45.000000', NULL, 1),
(6375398, 943919, 2553, '<td valign="top">Nicely done b&amp;w; love the contrast of texture and smoothness.</td>', 'Nicely done b&w; love the contrast of texture and smoothness.', '2011-04-05 20:54:44.000000', NULL, 1),
(6375399, 943888, 2553, '<td valign="top">Perfectly lovely!</td>', 'Perfectly lovely!', '2011-04-05 20:55:09.000000', NULL, 1),
(6375402, 944396, 2553, '<td valign="top">Wow, I''m just not sure what I love about this the most...most definitely the high-key rendering of the woman, but also the contrast of light and dark, as well as the fantasy/mystery aspect she projects.  Clearly a delightful combination of excellent camera work and superb model.  Probably my fav.</td>', 'Wow, I''m just not sure what I love about this the most...most definitely the high-key rendering of the woman, but also the contrast of light and dark, as well as the fantasy/mystery aspect she projects.  Clearly a delightful combination of excellent camera work and superb model.  Probably my fav.', '2011-04-05 20:57:41.000000', NULL, 1),
(6375413, 944180, 124982, '<td valign="top">This looks familiar :) Looks great in black&amp;white!</td>', 'This looks familiar :) Looks great in black&white!', '2011-04-05 21:06:41.000000', NULL, 1),
(6375414, 944462, 124982, '<td valign="top">Truck looks like it''s made from polished chrome!! Wonderful tones and contrast!</td>', 'Truck looks like it''s made from polished chrome!! Wonderful tones and contrast!', '2011-04-05 21:07:42.000000', NULL, 1),
(6375417, 944364, 124982, '<td valign="top">I think this is the first time I''ve seen a macro in B&amp;W! While I think it''s missing something with no color (monochromatic grey background is a little bland for me), I think it definitely enhances the textures and detail in the fly!</td>', 'I think this is the first time I''ve seen a macro in B&W! While I think it''s missing something with no color (monochromatic grey background is a little bland for me), I think it definitely enhances the textures and detail in the fly!', '2011-04-05 21:09:30.000000', NULL, 1),
(6375418, 944350, 124982, '<td valign="top">Hmmmm, YES! Love the minimalist feel to this. Incredibly elegant!</td>', 'Hmmmm, YES! Love the minimalist feel to this. Incredibly elegant!', '2011-04-05 21:09:55.000000', NULL, 1),
(6375420, 943953, 124982, '<td valign="top">Such a quizzical look on this pooches face!! Priceless!</td>', 'Such a quizzical look on this pooches face!! Priceless!', '2011-04-05 21:11:24.000000', NULL, 1),
(6375495, 943774, 30982, '<td valign="top">An excellent find, well photographed.</td>', 'An excellent find, well photographed.', '2011-04-05 22:55:27.000000', NULL, 1),
(6375496, 943739, 30982, '<td valign="top">Really nice colection of lines and shapes.  Works quite well in B&amp;W.</td>', 'Really nice colection of lines and shapes.  Works quite well in B&W.', '2011-04-05 22:56:17.000000', NULL, 1),
(6375498, 944536, 30982, '<td valign="top">Poor thing is missing a few legs.  Harsh photo, but somehow suits the subject matter.  I''d prefer more of a background/environment, but that''s a personal taste kinda thing.</td>', 'Poor thing is missing a few legs.  Harsh photo, but somehow suits the subject matter.  I''d prefer more of a background/environment, but that''s a personal taste kinda thing.', '2011-04-05 22:57:06.000000', NULL, 1),
(6375502, 944574, 30982, '<td valign="top">Very nice exposure and tones; excellent detail in your tethered boat.  Feels a bit lonely, but peaceful.</td>', 'Very nice exposure and tones; excellent detail in your tethered boat.  Feels a bit lonely, but peaceful.', '2011-04-05 22:58:58.000000', NULL, 1),
(6375503, 944527, 30982, '<td valign="top">A very strong portrait!  Perfect in B&amp;W.</td>', 'A very strong portrait!  Perfect in B&W.', '2011-04-05 22:59:22.000000', NULL, 1),
(6375504, 943683, 30982, '<td valign="top">LOL!  Then why convert to B&amp;W??</td>', 'LOL!  Then why convert to B&W??', '2011-04-05 22:59:39.000000', NULL, 1),
(6375505, 944331, 124982, '<td valign="top">Hey Niall! I can certainly see why this entry is getting you a PB...wonderful detail! Particularly in the creases on the hand between the fingers and in the feather itself. Only thing I didn''t "like" was the half-a-head in the background.</td>', 'Hey Niall! I can certainly see why this entry is getting you a PB...wonderful detail! Particularly in the creases on the hand between the fingers and in the feather itself. Only thing I didn''t "like" was the half-a-head in the background.', '2011-04-05 22:59:48.000000', NULL, 1),
(6375507, 944406, 30982, '<td valign="top">Has a sense of a catalog no longer relevant.  A history from which we''ve moved on.  I like it.</td>', 'Has a sense of a catalog no longer relevant.  A history from which we''ve moved on.  I like it.', '2011-04-05 23:00:55.000000', NULL, 1),
(6375509, 943733, 30982, '<td valign="top">Wow.  Were I to offer a guess, I''d say either Steve or Colleen.  Very powerful sense of, well, power, for some reason.  Energy flow.  A dance of light.  Whatever.  I like it.</td>', 'Wow.  Were I to offer a guess, I''d say either Steve or Colleen.  Very powerful sense of, well, power, for some reason.  Energy flow.  A dance of light.  Whatever.  I like it.', '2011-04-05 23:02:06.000000', NULL, 1),
(6375512, 944563, 30982, '<td valign="top">Just a wee bit on the quirky side.  I get called quirky all the time, so I can''t tell you if that''s a good thing or a bad thing... Nice shallow DOF, though!</td>', 'Just a wee bit on the quirky side.  I get called quirky all the time, so I can''t tell you if that''s a good thing or a bad thing... Nice shallow DOF, though!', '2011-04-05 23:02:41.000000', NULL, 1),
(6375514, 944273, 30982, '<td valign="top">Island paradise.  I like the teensy figures in the distance.  Nice conversion!</td>', 'Island paradise.  I like the teensy figures in the distance.  Nice conversion!', '2011-04-05 23:03:04.000000', NULL, 1),
(6375518, 943347, 30982, '<td valign="top">Great textures.  Even more intriguing if you crop the top part of the wrist.  Nicely lit, well exposed, too.</td>', 'Great textures.  Even more intriguing if you crop the top part of the wrist.  Nicely lit, well exposed, too.', '2011-04-05 23:03:44.000000', NULL, 1),
(6375519, 944591, 30982, '<td valign="top">Wonderfully real, excellent tones and textures!</td>', 'Wonderfully real, excellent tones and textures!', '2011-04-05 23:04:00.000000', NULL, 1),
(6375527, 944344, 30982, '<td valign="top">Lovely detail on the rose!  There''s a bit of a dark halo surrounding it - looks a bit like a processing artifact.  Still, very lovely tones and textures here.</td>', 'Lovely detail on the rose!  There''s a bit of a dark halo surrounding it - looks a bit like a processing artifact.  Still, very lovely tones and textures here.', '2011-04-05 23:07:04.000000', NULL, 1),
(6375530, 944166, 30982, '<td valign="top">Very nice low-light kinda shot - works very well in the wide aspect ratio, too.</td>', 'Very nice low-light kinda shot - works very well in the wide aspect ratio, too.', '2011-04-05 23:08:03.000000', NULL, 1),
(6375531, 944529, 30982, '<td valign="top">pointandshoot got a dog??  Delightful!!</td>', 'pointandshoot got a dog??  Delightful!!', '2011-04-05 23:08:58.000000', NULL, 1),
(6375532, 944180, 30982, '<td valign="top">Classic and nicely done!</td>', 'Classic and nicely done!', '2011-04-05 23:09:15.000000', NULL, 1),
(6375534, 944052, 30982, '<td valign="top">What lovely light to catch them in - and with a breeze as well.  Well seen, excellent exposure.  I quite like the corner of light behind, too - thanks for not cropping that out.</td>', 'What lovely light to catch them in - and with a breeze as well.  Well seen, excellent exposure.  I quite like the corner of light behind, too - thanks for not cropping that out.', '2011-04-05 23:09:59.000000', NULL, 1),
(6375535, 944479, 30982, '<td valign="top">Very provocative and engaging portrait!</td>', 'Very provocative and engaging portrait!', '2011-04-05 23:10:15.000000', NULL, 1),
(6375536, 944596, 30982, '<td valign="top">Smile!  Wonderful exercise in tones, textures, shapes.  And a pigeon.  You can never go wrong with a pigeon, in my opinion.</td>', 'Smile!  Wonderful exercise in tones, textures, shapes.  And a pigeon.  You can never go wrong with a pigeon, in my opinion.', '2011-04-05 23:10:57.000000', NULL, 1),
(6375592, 944590, 30982, '<td valign="top">Interesting how the undulations fo the ground echo the turbulence in the sky.</td>', 'Interesting how the undulations fo the ground echo the turbulence in the sky.', '2011-04-05 23:32:11.000000', NULL, 1),
(6375593, 943462, 16106, '<td valign="top">I would have saved this for fine art. It has that weird slant that would fit there, and here im afraid it will pick up some anti nude scores. Its my pick for blue with a 10. the composition and mix of texture are just great.</td>', 'I would have saved this for fine art. It has that weird slant that would fit there, and here im afraid it will pick up some anti nude scores. Its my pick for blue with a 10. the composition and mix of texture are just great.', '2011-04-05 23:32:25.000000', NULL, 1),
(6375594, 943739, 16106, '<td valign="top">Very nice. you''ve got a great graphic sensibility, it almost looks like an ink drawing, yet you lost none of the documentary value. not an easy line to straddle.</td>', 'Very nice. you''ve got a great graphic sensibility, it almost looks like an ink drawing, yet you lost none of the documentary value. not an easy line to straddle.', '2011-04-05 23:32:35.000000', NULL, 1),
(6375595, 944376, 30982, '<td valign="top">Very nice use of the strong compositional elements of the architecture; the people, of course, make the shot.  Great title, too.</td>', 'Very nice use of the strong compositional elements of the architecture; the people, of course, make the shot.  Great title, too.', '2011-04-05 23:32:41.000000', NULL, 1),
(6375597, 944433, 16106, '<td valign="top">Im not a huge fan of blur, but it suits your subject so well that her it really works for you. Top five.</td>', 'Im not a huge fan of blur, but it suits your subject so well that her it really works for you. Top five.', '2011-04-05 23:33:43.000000', NULL, 1),
(6375598, 944272, 30982, '<td valign="top">Excellent story and the grain serves this well.</td>', 'Excellent story and the grain serves this well.', '2011-04-05 23:35:05.000000', NULL, 1),
(6375600, 944396, 16106, '<td valign="top">Nice glowing quality, with all the technicals nailed down tight. The tilt is a bit strong for my tastes but its still a top five in my book.</td>', 'Nice glowing quality, with all the technicals nailed down tight. The tilt is a bit strong for my tastes but its still a top five in my book.', '2011-04-05 23:35:52.000000', NULL, 1),
(6375603, 944578, 16106, '<td valign="top">beautiful tones, the full zone system on display. The cliff face is perfectly placed to push the eye back into the frame</td>', 'beautiful tones, the full zone system on display. The cliff face is perfectly placed to push the eye back into the frame', '2011-04-05 23:37:22.000000', NULL, 1),
(6375606, 943754, 16106, '<td valign="top">Its a shame you lost some of the detail in the shadows to deep black, but the framing makes this a very dramatic study, top ten</td>', 'Its a shame you lost some of the detail in the shadows to deep black, but the framing makes this a very dramatic study, top ten', '2011-04-05 23:38:48.000000', NULL, 1),
(6375608, 944135, 16106, '<td valign="top">lovely sense of balance and tranquility. I just wish you had a pure black here, it is the only flaw in this very strong image.</td>', 'lovely sense of balance and tranquility. I just wish you had a pure black here, it is the only flaw in this very strong image.', '2011-04-05 23:40:08.000000', NULL, 1),
(6375610, 944493, 16106, '<td valign="top">You have made this flower sing. I love all the details in the petals.</td>', 'You have made this flower sing. I love all the details in the petals.', '2011-04-05 23:40:52.000000', NULL, 1),
(6375612, 944554, 30982, '<td valign="top">Sublime tones with detail throughout; shy touches of light in just the right places.</td>', 'Sublime tones with detail throughout; shy touches of light in just the right places.', '2011-04-05 23:41:11.000000', NULL, 1),
(6375613, 944288, 30982, '<td valign="top">Wonderful perspective!</td>', 'Wonderful perspective!', '2011-04-05 23:41:23.000000', NULL, 1),
(6375614, 944381, 30982, '<td valign="top">You''ve gotta love that face!</td>', 'You''ve gotta love that face!', '2011-04-05 23:41:36.000000', NULL, 1),
