(6380949, 943783, 124815, '<td valign="top">A plane in the sky close to tall buildings .... My view is forever doomed. 7</td>', 'A plane in the sky close to tall buildings .... My view is forever doomed. 7', '2011-04-10 00:38:15.000000', NULL, 1),
(6380951, 944245, 124815, '<td valign="top">Yes, facets of fear.  (Penny?)</td>', 'Yes, facets of fear.  (Penny?)', '2011-04-10 00:42:34.000000', NULL, 1),
